<section><h1><?=H::e($service['title'])?></h1><p><?=nl2br(H::e($service['description']))?></p><p><strong><?=H::money($service['price'])?></strong> · <?=$service['turnaround_days']?> day turnaround · <?=$service['included_revisions']?> revisions included</p><?php foreach($images as $image):?><img class="product-preview" src="<?=H::e($image['image_path'])?>" alt="Custom design example"><?php endforeach?><?php foreach($errors as $e):?><p class="alert error"><?=H::e($e)?></p><?php endforeach?><?php if(H::user()):?><form method="post" action="/custom-design/<?=H::e($service['slug'])?>/purchase" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><h2>Your design brief</h2><?php foreach(['design_request'=>'Detailed design request *','required_text'=>'Required wording/names/text *','design_direction'=>'Theme/style/design direction *','color_preferences'=>'Color preferences','dimensions'=>'Size/dimensions','file_format'=>'Requested file format','intended_use'=>'Intended use/license needs','additional_notes'=>'Additional notes'] as $name=>$label):?><label><?=$label?><textarea name="<?=$name?>"><?=H::e($_POST[$name]??'')?></textarea></label><?php endforeach?><?php if($service['buyer_instructions']):?><p><?=nl2br(H::e($service['buyer_instructions']))?></p><?php endif?><?php foreach($questions as $q):?><label><?=H::e($q['question_text'])?><?=$q['is_required']?' *':''?><textarea name="answers[<?=$q['id']?>]" <?=$q['is_required']?'required':''?>></textarea></label><?php endforeach?><label>Reference files (JPG, PNG, WEBP, PDF; 25MB each)<input type="file" name="references[]" multiple accept="image/jpeg,image/png,image/webp,application/pdf"></label><p>Available marketplace credit: <strong><?=H::money($balances['available']??0)?></strong></p><label><input type="checkbox" name="use_credits" value="1" <?=((float)($balances['available']??0)>0)?'':'disabled'?>> Use available marketplace credit</label><h2>Billing address</h2><?php foreach(['billing_line1'=>'Address','billing_city'=>'City','billing_state'=>'State','billing_postal_code'=>'Postal code','billing_country'=>'Country code'] as $n=>$l):?><label><?=$l?><input name="<?=$n?>" required></label><?php endforeach?><button>Continue to secure checkout</button></form><?php else:?><p><a href="/login">Sign in to request this design</a>.</p><?php endif?></section>
